<?php
namespace App\Http\Controllers;
use App\Models\{Order,Product};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class OrderController extends Controller {
 public function checkout(){ $cart=session('cart',[]);abort_if(!$cart,redirect('/keranjang'));$products=Product::whereIn('id',array_keys($cart))->get()->keyBy('id');$total=0;foreach($cart as $id=>$q)if(isset($products[$id]))$total+=$products[$id]->price*$q;return view('checkout',compact('cart','products','total'));}
 public function store(Request $r){$d=$r->validate(['customer_name'=>'required|max:120','phone'=>'required|max:30','address'=>'required','notes'=>'nullable']);$cart=session('cart',[]);abort_if(!$cart,redirect('/keranjang'));$order=DB::transaction(function()use($cart,$d,$r){$ps=Product::whereIn('id',array_keys($cart))->lockForUpdate()->get()->keyBy('id');$total=0;foreach($cart as $id=>$q){$p=$ps->get($id);if(!$p||$p->stock<$q)throw \Illuminate\Validation\ValidationException::withMessages(['stok'=>'Stok berubah, periksa keranjang.']);$total+=$p->price*$q;}$o=Order::create(['user_id'=>$r->user()->id,'order_number'=>'SM-'.strtoupper(Str::random(8)),'customer_name'=>$d['customer_name'],'phone'=>$d['phone'],'address'=>$d['address'],'payment_method'=>'COD','total'=>$total,'status'=>'Menunggu konfirmasi','notes'=>$d['notes']??null]);foreach($cart as $id=>$q){$p=$ps->get($id);$o->items()->create(['product_id'=>$id,'product_name'=>$p->name,'price'=>$p->price,'quantity'=>$q,'subtotal'=>$p->price*$q]);$p->decrement('stock',$q);}return $o;});session()->forget('cart');return redirect()->route('orders.mine')->with('success','Pesanan berhasil dibuat: '.$order->order_number);}
 public function mine(){$orders=Order::with('items')->where('user_id',auth()->id())->latest()->paginate(10);return view('orders',compact('orders'));}
}